import{_ as a}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as s,c as t,a as i}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const b=JSON.parse(`{"title":"What's new in v1.10.0","description":"Native regex support — search with /pattern/flags syntax, automatic API term extraction, top-level alternation and --regex-hint override.","frontmatter":{"title":"What's new in v1.10.0","description":"Native regex support — search with /pattern/flags syntax, automatic API term extraction, top-level alternation and --regex-hint override.","date":"2026-03-13T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-10-0.md","filePath":"blog/release-v1-10-0.md"}`),n={name:"blog/release-v1-10-0.md"};function r(h,e,o,l,p,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="what-s-new-in-github-code-search-v1-10-0" tabindex="-1">What&#39;s new in github-code-search v1.10.0 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-10-0" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.10.0&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.10.0" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.10.0</a></p></blockquote><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="regex-query-syntax" tabindex="-1">Regex query syntax <a class="header-anchor" href="#regex-query-syntax" aria-label="Permalink to &quot;Regex query syntax&quot;">​</a></h3><p><code>github-code-search</code> now supports <strong>full regex queries</strong> using the <code>/pattern/flags</code> notation — the same syntax accepted by the GitHub web search UI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Any import of axios, regardless of quote style</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;/from.*[&#39;</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;">\\&quot;\\\`</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">]axios/&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> my-org</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Axios pinned to any semver-prefix in package.json</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &#39;/&quot;axios&quot;: &quot;[~^]?[0-9]&quot;/ filename:package.json&#39;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> my-org</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Legacy require() calls for a specific module</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;/require</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">([&#39;</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">](old-lib)[&#39;</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">)/&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> my-org</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># TODO, FIXME or HACK comments in one query</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;/TODO|FIXME|HACK/&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> my-org</span></span></code></pre></div><p>Because the GitHub Code Search API does not support regex natively, the CLI automatically extracts a representative literal term from the pattern to send to the API, then <strong>filters the returned results locally</strong> with the full regex. In the vast majority of cases this is entirely transparent.</p><h3 id="automatic-api-term-extraction" tabindex="-1">Automatic API term extraction <a class="header-anchor" href="#automatic-api-term-extraction" aria-label="Permalink to &quot;Automatic API term extraction&quot;">​</a></h3><p>The extraction algorithm picks the <strong>longest unambiguous literal sequence</strong> from the regex:</p><ul><li><code>/require\\([&#39;&quot;]axios[&#39;&quot;]\\)/</code> → sends <code>require</code> to the API</li><li><code>/&quot;version&quot;: &quot;\\d+\\.\\d+/</code> → sends <code>&quot;version&quot;: &quot;</code> to the API</li><li><code>/TODO|FIXME|HACK/</code> → sends <code>TODO OR FIXME OR HACK</code> (see below)</li></ul><p>If no term of 3+ characters can be extracted, the CLI exits with a clear error and instructs you to use <code>--regex-hint</code>.</p><h3 id="top-level-alternation-—-no-results-missed" tabindex="-1">Top-level alternation — no results missed <a class="header-anchor" href="#top-level-alternation-—-no-results-missed" aria-label="Permalink to &quot;Top-level alternation — no results missed&quot;">​</a></h3><p>When the regex pattern contains a <strong>top-level <code>|</code></strong> (not nested inside <code>(...)</code> or <code>[...]</code>), the CLI automatically builds an <code>A OR B OR C</code> GitHub query so that <strong>every branch is covered</strong> by the API fetch — not just the first one.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Sends: &quot;TODO OR FIXME OR HACK&quot; to the GitHub API</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;/TODO|FIXME|HACK/&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> my-org</span></span></code></pre></div><h3 id="regex-hint-—-manual-api-term-override" tabindex="-1"><code>--regex-hint</code> — manual API term override <a class="header-anchor" href="#regex-hint-—-manual-api-term-override" aria-label="Permalink to &quot;\`--regex-hint\` — manual API term override&quot;">​</a></h3><p>For patterns where the auto-extracted term is too short or too broad, use <code>--regex-hint</code> to specify exactly what the API should search for, while the <strong>full regex is still applied locally</strong> to filter results:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &#39;/&quot;axios&quot;:\\s*&quot;[~^]?[0-9]/ filename:package.json&#39;</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> my-org</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --regex-hint</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &#39;&quot;axios&quot;&#39;</span></span></code></pre></div><p><code>--regex-hint</code> is also recorded in the <strong>replay command</strong> included in the markdown output, so the exact same result set can be reproduced without re-triggering the warning.</p><h3 id="accurate-match-highlighting" tabindex="-1">Accurate match highlighting <a class="header-anchor" href="#accurate-match-highlighting" aria-label="Permalink to &quot;Accurate match highlighting&quot;">​</a></h3><p>In regex mode the TUI highlights the <strong>actual regex match positions</strong> inside each code fragment — not the approximate positions returned by the GitHub API for the literal search term. Match locations in the output (<code>:line:col</code> suffixes and <code>#L</code> GitHub anchors) reflect the true match boundaries.</p><h3 id="invalid-regex-is-always-a-hard-error" tabindex="-1">Invalid regex is always a hard error <a class="header-anchor" href="#invalid-regex-is-always-a-hard-error" aria-label="Permalink to &quot;Invalid regex is always a hard error&quot;">​</a></h3><p>Malformed patterns (e.g. unclosed groups, bad escape sequences) are detected at startup and produce a clear fatal error before any API call is made:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>⚠  Regex mode — Invalid regex /foo(/: Unterminated group</span></span></code></pre></div><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Or grab the latest binary directly from the <a href="https://github.com/fulll/github-code-search/releases/tag/v1.10.0" target="_blank" rel="noreferrer">GitHub Releases page</a>.</p>`,27)])])}const y=a(n,[["render",r]]);export{b as __pageData,y as default};
